entries[156322] = { ["name"] = "Ewige Flamme", ["text"] = "3 Heilige Kraft / 0.6% von Grundmana 40 Meter Reichweite\nSofort\nHeilig\nHeilt einen Verbündeten um (315% der Zaubermacht) Gesundheit sowie im Verlauf von 16 Sek. zusätzlich um (91.2% der Zaubermacht) Gesundheit.\n\nDie Heilung ist um 25% erhöht, wenn Ihr Euch selbst heilt.\n\nVergeltung\nHeilt einen Verbündeten um (315% der Zaubermacht) Gesundheit sowie im Verlauf von 16 Sek. zusätzlich um (91.2% der Zaubermacht) Gesundheit.\n\nDie Heilung ist um 35% erhöht, wenn Ihr Euch selbst heilt." }
entries[156323] = { ["name"] = "Kauterisierender Blitz", ["text"] = "Unbegrenzte Reichweite\nSofort\nKauterisiert die Wunden eines Ziels und seiner Verbündeten im Umkreis von 5 Metern. Fügt dem Ziel und seinen Verbündeten sofort 20% ihrer gesamten Gesundheit als Schaden zu. Stellt danach im Verlauf von 10 Sek. bis zu (1.5 * 20)% ihrer gesamten Gesundheit wieder her. Ein Großteil dieser Heilung geschieht schnell." }
entries[156324] = { ["name"] = "Säurestrom", ["text"] = "100 Meter Reichweite\nSofort\nVersprüht Säure in einem kegelförmigen Bereich auf einen zufälligen entfernten Gegner, die dem nächststehenden Spielercharakter 34766 körperlichen Schaden zufügt und den von ihm durch 'Säurestrom' erlittenen Schaden 20 Sek. lang um 34766 erhöht. Alle anderen Ziele erleiden bis zu 17383 Naturschaden, der durch die gesamte Schadensmitigation des Primärziels verringert wird." }
