entries[156581] = { ["name"] = "Draenischer Trank der Manakanalisierung", ["text"] = "Wirken in 2 sek.\nOhne Beruf:\nReagenzien:\nKristallphiole , Sternenblume (3)\nVerkäufer:\nJoshua Alvarez\nZone:\nKriegsspeer\nKosten:\n9\n\nBenutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 255 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\n35" }
entries[156582] = { ["name"] = "Draenischer Manatrank", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKristallphiole , Gorgrondfliegenfalle (3)\nVerkäufer:\nAlbert de Hyde\nGegenstand:\nEine Abhandlung über die Alchemie Draenors\nKosten:\n100\nZone:\nFrostwall\n\nVerkäufer:\nJoshua Alvarez\nGegenstand:\nEine Abhandlung über die Alchemie Draenors\nKosten:\n100\nZone:\nAshran\n\nBenutzen: Stellt 1700 Mana wieder her. (5 Min Abklingzeit)\n35" }
