entries[156586] = { ["name"] = "Alchemistenkessel", ["text"] = "Wirken in 3.5 sek. 1 tag Abklingzeit\nReagenzien:\nUressenz (3), Schwarzfelserz (3)\nLiefert die erforderlichen Reagenzien, um die mächtigsten alchemistischen Gegenstände von Draenor zu erschaffen. Kann nur einmal am Tag verwendet werden. Teilt eine Abklingzeit mit anderen Alchemistenkesseln." }
entries[156587] = { ["name"] = "Alchemischer Katalysator", ["text"] = "Wirken in 1.5 sek. 1 tag Abklingzeit\nReagenzien:\nFrostwurz (20), Schwarzfelserz (10)\nProduziert 8 (plus zusätzliche, je nach Alchemiefertigkeit).\n\nKann auch magisches Feuer und/oder magisches Wasser erzeugen.\n\nDie Abklingzeit wird täglich abgeschlossen.\nVerkäufer:\nMary Kearie\nGegenstand:\nEine Abhandlung über die Alchemie Draenors\nKosten:\n100\nZone:\nMondsturz\n\nVerkäufer:\nKatherine Joplin\nGegenstand:\nEine Abhandlung über die Alchemie Draenors\nKosten:\n100\nZone:\nAshran\n\nAlchemischer Katalysator\nHandwerksmaterial\n\"Beschleunigt Reaktionen, die sonst Tausende von Jahren benötigen würden, und ist daher unerlässlich für die Alchemie auf Draenor.\"" }
